def count_positives_by_digit_sum(nums):
    """
    Counts positive integers in a list, grouped by the sum of their digits.

    Args:
        nums (list): A list of integers.

    Returns:
        dict: A dictionary where keys are digit sums and values are counts
              of positive integers with that digit sum.
    """
    def digit_sum(n):
        """Calculate the sum of digits of a non-negative integer."""
        return sum(int(d) for d in str(n))

    # Filter positive numbers, calculate digit sum, and count occurrences
    return {
        sum_digits: count
        for sum_digits, count in (
            (digit_sum(n), 1)
            for n in nums if n > 0
        )
    }

