def count_parentheses_balance(expression):
    """
    Counts the balance of parentheses and ensures no closing parenthesis appears before an opening one.

    :param expression: A string containing parentheses '(', ')'
    :return: A dictionary with 'balanced' (bool), 'balance_count' (int), and 'valid_order' (bool)
    """
    balance_count = 0
    valid_order = True

    for char in expression:
        if char == '(':
            balance_count += 1
        elif char == ')':
            balance_count -= 1
            if balance_count < 0:
                valid_order = False

    # Check if fully balanced (ends at 0) and order was valid
    is_balanced = (balance_count == 0) and valid_order

    return {
        'balanced': is_balanced,
        'balance_count': balance_count,
        'valid_order': valid_order
    }

