def count_non_overlapping_occurrences(s: str, sub: str) -> int:
    """
    Count non-overlapping occurrences of substring `sub` in string `s`
    by iterating through each starting index and checking if the suffix
    starts with the substring.
    """
    len_s = len(s)
    len_sub = len(sub)

    if len_sub == 0:
        return 0

    return sum(
        1
        for i in range(len_s - len_sub + 1)
        if s[i:].startswith(sub)
    )

