def sum_small_digits(arr, k):
    """
    Sums first k elements of array that have 2 or fewer digits.
    Digits count includes minus sign for negatives.

    Args:
        arr: List of numbers
        k: Number of elements to sum (first k matching the criteria)

    Returns:
        Sum of first k elements with 2 or fewer digits
    """
    def count_digits(num):
        """Count digits including minus sign for negatives."""
        return len(str(num))

    def has_two_or_fewer_digits(num):
        """Check if number has 2 or fewer digits."""
        return count_digits(num) <= 2

    # Filter and take first k elements, then sum
    return sum(
        num for num in arr 
        if has_two_or_fewer_digits(num)
    )[:k]
