from typing import List, Any

def insert_delimiter(elements: List[Any], delimiter: Any) -> List[Any]:
    """
    Inserts a delimiter between list elements.

    Args:
        elements: The list of elements to process
        delimiter: The delimiter to insert between elements

    Returns:
        A new list with the delimiter inserted between each element

    Example:
        >>> insert_delimiter([1, 2, 3], ',')
        [1, ',', 2, ',', 3]
    """
    if not elements:
        return []

    def insert_between(acc, remaining):
        if not remaining:
            return acc
        if not acc:
            return insert_between([remaining[0]], remaining[1:])
        return insert_between(acc + [delimiter, remaining[0]], remaining[1:])

    return insert_between([], elements)

